@startuml

class Person {}

class Student extends Person {
  + name : string
  + email : string
}

class Tutor extends Person {
  + name : string
  + email : string
  + bankAccount : string
}

class Subject {}

class ExpertiseLevel {}

class TutoringOffer {
  + hourlyPrice : float
}

class Availability {
  + dayOfWeek : string
  + startTime : time
  + endTime : time
}

class TutoringRequest {
  + targetDate : date
  + targetTime : time
  + level : ExpertiseLevel
}

class TutoringSession {
  + actualDate : date
  + actualTime : time
  + status : string
}

class Payment {
  + amount : float
  + method : string
}

Tutor "1" -- "*" TutoringOffer : offers
TutoringOffer "*" -- "1" Subject : in
Tutor "1" -- "*" Availability : specifies
Tutor "1" -- "*" TutoringOffer : provides expertise
Tutor "1" -- "*" TutoringOffer : has expertise level
TutoringOffer "*" -- "1" ExpertiseLevel : at level

Student "1" -- "*" TutoringRequest : makes
TutoringRequest "*" -- "1" Tutor : to
TutoringRequest "*" -- "1" Subject : for
TutoringRequest "*" -- "1" ExpertiseLevel : at level

TutoringRequest "0..1" -- "0..1" TutoringSession : becomes
TutoringSession "*" -- "1" Student : attended by
TutoringSession "*" -- "1" Tutor : attended by
TutoringSession "1" -- "1" Payment : paid via

@enduml

